const fs=require('node:fs'),assert=require('node:assert/strict'),{chromium,webkit}=require('playwright');const engine=process.env.NATIVE_BROWSER||'chromium',out='qa-output/line-'+engine;fs.mkdirSync(out,{recursive:true});const specs=JSON.parse(fs.readFileSync('research/full-head-cases/manifest.json'));
(async()=>{const b=await({chromium,webkit}[engine]).launch(engine==='chromium'?{headless:true,args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']}:{headless:true}),page=await b.newPage({viewport:{width:1440,height:1000}}),errors=[],rows=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:8765/qa/common-native.html?head=1');await page.waitForFunction(()=>window.commonNativeQA?.ready,null,{timeout:180000});const state=specs.cases.find(x=>x.name==='anny-neutral');await page.evaluate(s=>window.commonNativeQA.apply(s),state.state);await page.evaluate(()=>window.commonNativeQA.view('front'));for(const source of['common','native-anny']){if(source==='native-anny')await page.evaluate(r=>window.commonNativeQA.showNative(r),state);for(const mode of['baseline','precise-depth','unlit']){const diagnostic=await page.evaluate(m=>window.commonNativeQA.renderingDiagnostic(m),mode);assert.equal((await page.evaluate(()=>window.commonNativeQA.pixel())).error,0);await page.screenshot({path:out+'/'+source+'-'+mode+'.png'});rows.push({source,...diagnostic});}rows.push({source,rays:await page.evaluate(()=>window.commonNativeQA.rayDiagnostic([[536,535],[520,570],[503,605],[491,628],[965,720],[996,660]]))});}assert.deepEqual(errors,[]);fs.writeFileSync(out+'/report.json',JSON.stringify({engine,rows,errors,geometryNotModified:true,interpretationPendingPixelComparison:true},null,2));await b.close();})().catch(e=>{console.error(e);process.exit(1)});
